import {dayKey,parseDay,makePlan,relevantChunks} from './planner.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>dayKey(new Date());
let state={exams:[],sessions:[],minutes:90};try{Object.assign(state,JSON.parse(localStorage.getItem('tuonta-v1')||'{}'))}catch{}
let view=new URLSearchParams(location.search).get('view')||'home',month=new Date(),busy=false,docText='',docName='',transcript=[];
const save=()=>{try{localStorage.setItem('tuonta-v1',JSON.stringify(state))}catch{toast('Browser storage is full or unavailable. Your changes are kept for this visit.')}};
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===view));
$('#header-action').onclick=()=>{if(view==='home')$('#tools').scrollIntoView({behavior:'smooth'});else if(view==='planner')$('#subject').focus();else $('#question').focus()};
function home(){$('#app').innerHTML=`<section class="hero"><div><span class="eyebrow">Your potential, with a plan</span><h1>A little plan.<br>A lot of<br><em>possibility.</em></h1><p>Big dreams start with small study sessions. Turn your exam dates and messy notes into a plan that works for you.</p><div class="hero-actions"><a class="button coral" href="?view=planner" target="_blank" rel="noopener">▦ &nbsp; Plan my studies</a><a class="button light" href="?view=chat" target="_blank" rel="noopener">✧ &nbsp; Meet my study buddy</a></div><div class="little-proof"><div class="avatars"><span>👩🏽</span><span>👨🏻</span><span>👩🏾</span></div><span>For curious minds. And very full calendars.</span></div></div><div class="hero-art" aria-label="Illustration of a weekly study plan"><div class="art-grid"></div><div class="art-orbit"></div><span class="spark">✳</span><span class="spark two">✧</span><div class="floating first"><span class="bubble">✓</span><div><strong>You’ve got a plan.</strong>One less thing on your mind.</div></div><div class="planner-preview"><div class="preview-top"><span class="preview-logo">✳ TuonTa.</span><span>My study space &nbsp; •••</span></div><div class="preview-main"><div class="preview-title">A good week starts here ☀</div><div class="preview-sub">A little focus, a little progress. You’ve got this.</div><div class="preview-days">MON TUE WED THU FRI SAT SUN<b>12</b><b>13</b><b>14</b><b>15</b><b>16</b><b>17</b><b>18</b></div><div class="preview-task"><span>▦ &nbsp; Biology · Cell structures</span><span>30 min</span></div><div class="preview-task"><span>✧ &nbsp; Chemistry · Quick recall</span><span>25 min</span></div></div></div><div class="note-sticker">Progress over<br>perfection. ♡</div><div class="floating second"><span style="font-size:25px">✦</span><div><strong>Your study sidekick</strong>A little help. A lot more clarity.</div></div></div></section><div class="trust-strip"><span><b>✧</b> AI with a purpose</span><span><b>▦</b> Built around your exams</span><span><b>♡</b> Your pace, your progress</span><span><b>⌁</b> Free to start. Easy to love.</span></div><section class="tools-section" id="tools"><div class="section-intro"><div><span class="eyebrow">Two tools. One less overwhelmed you.</span><h2>Find your study flow.</h2></div><p>Make room for the “aha!” moments.<br>We’ll help you figure out the next step.</p></div><div class="tool-cards"><article class="tool-card"><div class="card-icon">▦</div><span class="pill">A PLAN THAT FITS YOU</span><h3>Your exams. A smarter plan.</h3><p>Give your exam dates a home. Turn the countdown into small, manageable study sessions.</p><div class="card-features"><span>✓ Exam calendar</span><span>✓ Personalized sessions</span><span>✓ AI guidance</span></div><a class="button dark" href="?view=planner" target="_blank" rel="noopener">Open study planner</a><span class="card-art">▦</span></article><article class="tool-card violet"><div class="card-icon">✧</div><span class="pill">YOUR ALWAYS-CURIOUS SIDEKICK</span><h3>Less confusion. More “got it.”</h3><p>Bring your class notes. Get summaries, simple explanations, and quizzes that help things click.</p><div class="card-features"><span>✓ Upload notes</span><span>✓ Ask questions</span><span>✓ Test yourself</span></div><a class="button dark" href="?view=chat" target="_blank" rel="noopener">Meet your study buddy</a><span class="card-art">✧</span></article></div></section><aside class="bottom-banner"><span class="plant">🌱</span><div><h3>You don’t have to have it all figured out.</h3><p>Just start with one subject, one question, one small step.</p></div><span>Let’s learn together.</span></aside>`}
function planner(){$('#app').innerHTML=`<div class="workspace"><div class="workspace-heading"><div><span class="eyebrow">A little structure. A clearer head.</span><h1>Make room for progress.</h1><p>Your exams set the destination. Let’s plan the small steps.</p></div><button class="button light" id="sample">Try sample exams</button></div><div class="work-grid"><aside><section class="panel"><h2>▦ Add an exam</h2><form id="exam-form"><label for="subject">Subject</label><input id="subject" maxlength="65" placeholder="e.g. Biology" required><label for="exam-date">Exam date</label><input type="date" id="exam-date" min="${today()}" required><label for="topics">Topics to focus on</label><input id="topics" maxlength="180" placeholder="e.g. Cells, genetics"><div class="form-row"><div><label for="difficulty">Confidence</label><select id="difficulty"><option value="3">Need help</option><option value="2" selected>Getting there</option><option value="1">Feeling good</option></select></div><div><label for="hours">Study hours</label><input id="hours" type="number" min="1" max="100" value="4" required></div></div><button class="button coral full" style="margin-top:20px" type="submit">+ Add exam</button></form><p class="hint">You can also click a date on the calendar.</p><div id="exams" class="exam-list"></div></section><section class="panel" style="margin-top:20px"><h2>Your daily study time</h2><label for="minutes">Minutes per day</label><select id="minutes"><option value="30">30 minutes · A gentle start</option><option value="60">60 minutes · Steady progress</option><option value="90">90 minutes · Finding my flow</option><option value="120">120 minutes · Deep focus</option></select><button class="button purple full" style="margin-top:18px" id="generate">✧ Build my study plan</button><p class="hint">Sessions stay within your daily limit and finish before each exam. Take a short break between sessions.</p><div id="plan-status" role="status"></div></section></aside><div><section class="panel"><div class="calendar-head"><h2 id="month-label"></h2><div class="calendar-controls"><button class="icon-button" id="prev" aria-label="Previous month">‹</button><button class="button light compact" id="today">Today</button><button class="icon-button" id="next" aria-label="Next month">›</button></div></div><div id="calendar" class="calendar"></div><div class="legend"><span>Exam day</span><span>Study session</span></div></section><section class="panel plan-panel"><div class="plan-head"><h2>Your next small steps</h2><button class="button light compact" id="export-plan">Export plan</button></div><p class="hint" id="progress"></p><div id="sessions"></div></section><section class="panel" style="margin-top:24px"><h2>✧ A little guidance from AI</h2><p class="hint">Get a short study suggestion based on your upcoming exams and available time. Hosted AI turns your exam dates and available time into practical study guidance.</p><button class="button light" id="coach">Get AI study guidance</button><div id="coach-result" role="status"></div></section></div></div></div>`;
 $('#minutes').value=state.minutes;$('#minutes').onchange=e=>{state.minutes=+e.target.value;state.sessions=[];save();renderCalendar();renderSessions();toast('Daily limit updated. Build your plan again.')};
 $('#exam-form').onsubmit=e=>{e.preventDefault();const date=$('#exam-date').value;if(date<today())return toast('Choose today or a future exam date.');state.exams.push({id:crypto.randomUUID(),subject:$('#subject').value.trim(),date,topics:$('#topics').value.trim(),difficulty:+$('#difficulty').value,hours:+$('#hours').value});state.sessions=[];month=parseDay(date);save();$('#exam-form').reset();renderPlanner();toast('Exam added. Build your plan when you’re ready.')};
 $('#prev').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);renderCalendar()};$('#next').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);renderCalendar()};$('#today').onclick=()=>{month=new Date();renderCalendar()};
 $('#sample').onclick=()=>{if(state.exams.length)return toast('Your calendar already has exams. Remove them before trying the sample.');state.exams=[['Biology','Cells & genetics',7,3,4],['Mathematics','Functions & equations',12,2,5],['English','Reading comprehension',16,1,3]].map(([subject,topics,offset,difficulty,hours])=>{const d=new Date();d.setDate(d.getDate()+offset);return{id:crypto.randomUUID(),subject,topics,date:dayKey(d),difficulty,hours}});save();renderPlanner();toast('Sample exams added. Try building your plan.')};
 $('#generate').onclick=()=>{state.sessions=makePlan(state.exams,{minutes:state.minutes});save();renderPlanner();if(!state.sessions.length)$('#plan-status').innerHTML='<div class="notice">Add an exam after today to schedule study sessions.</div>';else{const short=state.exams.filter(e=>e.date>today()).filter(e=>state.sessions.filter(s=>s.examId===e.id).reduce((n,s)=>n+s.minutes,0)<e.hours*60);$('#plan-status').innerHTML=`<div class="ai-status">${state.sessions.length} sessions planned. ${short.length?'Some requested hours do not fit before your exams. Increase daily time or lower your study-hour targets.':'You’ve got a manageable next step.'} Plans cover the next 90 days.</div>`}};
 $('#export-plan').onclick=()=>{if(!state.sessions.length)return toast('Build your study plan first.');download('tuonta-study-plan.csv','Date,Subject,Topic,Minutes,Method,Completed\n'+state.sessions.map(s=>[s.date,s.subject,s.topic,s.minutes,s.method,s.done?'Yes':'No'].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv')};
 $('#coach').onclick=async()=>{const exams=state.exams.filter(e=>e.date>=today());if(!exams.length)return toast('Add an upcoming exam first.');await runAI(`Give a specific study tip for a student. They have ${state.minutes} minutes a day. Their upcoming exams are ${exams.map(e=>e.subject+' on '+e.date+', topics '+e.topics).join('; ')}. What should they focus on first?`,$('#coach-result'),$('#coach'))};renderPlanner()}
function renderPlanner(){renderCalendar();renderSessions();$('#exams').innerHTML=state.exams.length?state.exams.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div class="exam-item"><div><strong>${escape(e.subject)}</strong><small>${prettyDate(e.date)} · ${e.hours}h goal</small></div><button class="icon-button" data-delete="${escape(e.id)}" aria-label="Delete ${escape(e.subject)} exam">×</button></div>`).join(''):'<p class="hint">A fresh start. Add your first exam above.</p>';document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{state.exams=state.exams.filter(e=>e.id!==b.dataset.delete);state.sessions=[];save();renderPlanner()})}
function prettyDate(d){return parseDay(d).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function renderCalendar(){const y=month.getFullYear(),m=month.getMonth();$('#month-label').textContent=month.toLocaleDateString(undefined,{month:'long',year:'numeric'});let html=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="weekday">${d}</div>`).join('');const offset=(new Date(y,m,1).getDay()+6)%7;html+='<div class="day empty"></div>'.repeat(offset);for(let n=1;n<=new Date(y,m+1,0).getDate();n++){const date=dayKey(new Date(y,m,n)),exams=state.exams.filter(e=>e.date===date),sessions=state.sessions.filter(s=>s.date===date);html+=`<button class="day ${date===today()?'today':''}" data-date="${date}" aria-label="${prettyDate(date)}, ${exams.length} exams, ${sessions.length} study sessions"><span>${n}</span>${exams.map(e=>`<span class="day-tag">${escape(e.subject)}</span>`).join('')}${sessions.length?`<span class="day-tag study">${sessions.length} to study</span>`:''}</button>`}$('#calendar').innerHTML=html;document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{if(b.dataset.date<today())return toast('Choose today or a future date for your exam.');$('#exam-date').value=b.dataset.date;$('#subject').focus();toast('Date selected. Add your exam details.')})}
function renderSessions(){const sessions=state.sessions.filter(s=>s.date>=today());$('#progress').textContent=state.sessions.length?`${state.sessions.filter(s=>s.done).length} of ${state.sessions.length} sessions complete · ${state.minutes} minutes maximum per day`:'';$('#sessions').innerHTML=sessions.length?sessions.slice(0,60).map(s=>`<label class="session ${s.done?'done':''}"><input type="checkbox" data-session="${s.id}" ${s.done?'checked':''}><span><strong>${escape(s.subject)} · ${escape(s.method)}</strong><small>${prettyDate(s.date)} · ${escape(s.topic)}</small></span><span class="duration">${s.minutes} min</span></label>`).join(''):'<div class="empty-state">🌱<br>Your next chapter starts with a plan.<br>Add exam dates, then build your study sessions.</div>';document.querySelectorAll('[data-session]').forEach(c=>c.onchange=()=>{const session=state.sessions.find(s=>s.id===c.dataset.session);session.done=c.checked;save();renderSessions()})}
function chat(){$('#app').innerHTML=`<div class="workspace"><div class="workspace-heading"><div><span class="eyebrow">Bring your notes. Find your clarity.</span><h1>Your curious little sidekick.</h1><p>Understand the material. Make it stick. One question at a time.</p></div></div><div class="work-grid"><aside><section class="panel"><h2>Your study material</h2><div class="upload"><span class="upload-symbol">♧</span><strong>Give your notes a home</strong><p class="hint">Upload a PDF, DOCX, TXT, or Markdown file. Up to 10 MB.</p><input id="upload" type="file" accept=".pdf,.docx,.txt,.md" aria-label="Upload study material"></div><div id="document-name" class="document-name" role="status">No document yet</div><button class="button light full" id="sample-doc">Try sample biology notes</button><div class="chat-actions"><button class="button purple" id="summarize">Summarize</button><button class="button light" id="notes">Make notes</button><button class="button light" id="quiz">Quiz me</button></div><p class="hint">Powered by Groq hosted AI. No model download needed. Ask a study question or upload a document for help.</p><div class="notice">Double-check AI answers against your original notes. Scanned PDFs need OCR before uploading.</div><div id="ai-load" role="status"></div></section><section class="panel" style="margin-top:20px"><h2>A little housekeeping</h2><p class="hint">Files are read in this tab. When you ask for AI help, document text and recent messages are sent securely to Groq through TuonTa’s server. The API key stays on the server.</p><button class="button light full" id="download-notes">Download conversation</button><button class="button light full" style="margin-top:10px" id="clear-chat">Clear conversation</button></section></aside><section class="panel chat-panel"><div class="chat-log" id="chat-log" role="log" aria-live="polite"><div class="chat-welcome"><div class="big-icon">✧</div><h2>Let’s make it click.</h2><p>Ask me a study question, or upload your notes.<br>I can explain concepts, summarize material, and help you practice.</p><div class="suggestions"><button data-prompt="What is the main idea?">Find the main idea</button><button data-prompt="Explain this in simple terms.">Explain it simply</button><button data-prompt="What should I remember for an exam?">What should I remember?</button></div></div></div><form class="composer" id="chat-form"><input id="question" placeholder="Ask something about your notes…" maxlength="500" aria-label="Question about your notes" required><button class="button purple" type="submit" id="send">Send</button></form><p class="hint" style="margin-bottom:0">Answers use relevant excerpts from your file. Upload English study materials for best results.</p></section></div></div>`;
 $('#upload').onchange=e=>loadDocument(e.target.files[0]);$('#sample-doc').onclick=()=>setDoc('Biology — cell essentials.txt',sampleText);$('#summarize').onclick=()=>documentTask('summary');$('#notes').onclick=()=>documentTask('notes');$('#quiz').onclick=()=>documentTask('quiz');$('#chat-form').onsubmit=e=>{e.preventDefault();ask($('#question').value)};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>ask(b.dataset.prompt));$('#clear-chat').onclick=()=>{if(busy)return toast('Wait for the current AI response to finish.');transcript=[];$('#chat-log').innerHTML='';toast('Conversation cleared. Your document is still loaded.')};$('#download-notes').onclick=()=>transcript.length?download('tuonta-study-notes.txt',transcript.map(m=>m.role+':\n'+m.text).join('\n\n')):toast('Start a conversation first.')}
const sampleText=`Cells are the basic structural and functional units of living organisms. The cell membrane controls which substances enter and leave the cell. It is selectively permeable. The cytoplasm is the jelly-like substance where many chemical reactions take place. The nucleus contains DNA and controls cell activities. Mitochondria release energy from glucose through cellular respiration. Ribosomes make proteins. Plant cells have a cell wall made of cellulose, a large central vacuole, and chloroplasts. Chloroplasts contain chlorophyll, which absorbs light energy for photosynthesis. Photosynthesis uses carbon dioxide, water, and light energy to make glucose and oxygen. Cellular respiration uses glucose and oxygen to release usable energy, carbon dioxide, and water. Diffusion is the movement of particles from a region of higher concentration to lower concentration. Osmosis is the movement of water across a selectively permeable membrane from higher water concentration to lower water concentration. Active transport moves substances against a concentration gradient and requires energy. DNA carries genetic instructions. Genes are sections of DNA that code for proteins. Mitosis produces two genetically identical daughter cells for growth and repair. Meiosis produces four genetically different gametes with half the chromosome number. The key difference between prokaryotic and eukaryotic cells is that eukaryotic cells have a membrane-bound nucleus, while prokaryotic cells do not.`;
function setDoc(name,text){if(busy)return toast('Wait for the current AI response before changing your file.');if(text.trim().length<40)return toast('This document has too little readable text. Try a text-based file.');docName=name;docText=text.slice(0,150000);transcript=[];$('#chat-log').innerHTML='';$('#document-name').textContent=`${name} · ${docText.length.toLocaleString()} characters`;addMessage('TuonTa',`Your document is ready: ${name}. Ask a question, make notes, or try a quiz.${text.length>150000?' Only the first 150,000 characters are included.':''}`)}
async function loadDocument(file){if(!file)return;if(busy){$('#upload').value='';return toast('Wait for the AI response before changing documents.')}if(file.size>10*1024*1024)return toast('Choose a file smaller than 10 MB.');$('#document-name').textContent='Reading your file…';try{let text;const ext=file.name.split('.').pop().toLowerCase();if(['txt','md'].includes(ext))text=await file.text();else if(ext==='pdf'){const pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs';const pdf=await pdfjs.getDocument({data:await file.arrayBuffer(),isEvalSupported:false}).promise;let pages=[];for(let i=1;i<=Math.min(pdf.numPages,80);i++){const page=await pdf.getPage(i);pages.push((await page.getTextContent()).items.map(x=>x.str).join(' '))}text=pages.join('\n\n');if(pdf.numPages>80)toast('The first 80 pages were read.')}else if(ext==='docx'){await loadScript('https://cdn.jsdelivr.net/npm/mammoth@1.9.0/mammoth.browser.min.js');text=(await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()})).value}else throw Error('Use PDF, DOCX, TXT, or Markdown.');setDoc(file.name,text)}catch(e){toast('Could not read this file. '+e.message)}finally{if(docName)$('#document-name').textContent=docName;else $('#document-name').textContent='No readable document loaded';$('#upload').value=''}}
function loadScript(src){return new Promise((resolve,reject)=>{if(window.mammoth)return resolve();const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>reject(Error('Document reader could not load.'));document.head.append(s)})}
function addMessage(role,text){transcript.push({role,text});const el=document.createElement('div');el.className='message '+(role==='You'?'user':'ai');const title=document.createElement('strong');title.textContent=role;el.append(title);const content=document.createElement('div');content.className='answer-body';content.innerHTML=escape(text).replace(/^#{1,4}\s+(.+)$/gm,'<b>$1</b>').replace(/\*\*([^*]+)\*\*/g,'<b>$1</b>').replace(/`([^`]+)`/g,'<code>$1</code>');el.append(content);$('#chat-log').append(el);el.scrollIntoView({block:'nearest'});return el}
async function invokeAI(prompt,status){status('Your study buddy is thinking…');const history=transcript.slice(-7,-1).filter(m=>m.role==='You'||m.role==='TuonTa').map(m=>({role:m.role==='You'?'user':'assistant',content:m.text}));const response=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt,history}),signal:AbortSignal.timeout(65000)});let result;try{result=await response.json()}catch{throw Error('The AI service could not be reached. Please refresh and try again.')}if(!response.ok)throw Error(result.error||'AI request failed.');return result.text}
async function runAI(prompt,target,button){if(busy){toast('One moment—your AI is working on another response.');return null}busy=true;if(button)button.disabled=true;target.className='ai-status busy';target.textContent='Warming up your study buddy…';try{const answer=await invokeAI(prompt,s=>target.textContent=s);target.textContent=answer;return answer}catch(e){target.textContent=e.message;return null}finally{busy=false;if(button)button.disabled=false;target.classList.remove('busy')}}
async function ask(question){if(busy)return toast('Wait for your current answer to finish.');question=question.trim();if(!question)return;$('#question').value='';addMessage('You',question);let source='',prompt=question;if(docText){const chunks=docText.length<=24000?[{content:docText,i:0}]:relevantChunks(docText,question,12);source=chunks.map(c=>`[Excerpt ${c.i+1}]\n${c.content}`).join('\n\n');prompt=`Answer the student's question using the reference document below. For a summary request, give a coherent overview and key points. Cite excerpt numbers when making factual claims. Say if the document does not contain the answer.\nDocument: ${docName}\n<reference>\n${source}\n</reference>\nQuestion: ${question}`}const answer=await runAI(prompt,$('#ai-load'),$('#send'));if(answer)addMessage('TuonTa',answer+(docText?`\n\nSource: ${docName}${docText.length>24000?' · selected relevant excerpts':''}`:''))}
function documentContext(){if(docText.length<=45000)return{text:docText,coverage:'All extracted text included.'};const parts=docText.match(/[\s\S]{1,5000}/g)||[docText];const indices=[...new Set(Array.from({length:9},(_,i)=>Math.floor(i*(parts.length-1)/8)))];return{text:indices.map(i=>`[Section ${i+1}]\n${parts[i]}`).join('\n\n'),coverage:'Selected sections across the document; some material is outside this summary.'}}
async function documentTask(kind){if(!docText)return toast('Upload your notes or try the sample first.');if(busy)return toast('Wait for your current answer to finish.');addMessage('You',({summary:'Summarize my document.',notes:'Make study notes from my document.',quiz:'Create a practice quiz from my document.'})[kind]);const context=documentContext();const task=kind==='summary'?'Write a clear summary of this document: one overview paragraph followed by 5–8 key points. Explain the substance rather than repeating headings.':kind==='notes'?'Create useful study notes with topic headings, key concepts and definitions, important examples from the material, and three things to remember. Explain each point clearly.':'Create 5 practice questions grounded in this document. Return ONLY JSON with this shape: {"questions":[{"question":"...","answer":"..."}]}. Include a mix of recall, understanding, and application. Answers must be supported by the document.';const answer=await runAI(`${task}\nDocument: ${docName}\n<reference>\n${context.text}\n</reference>`,$('#ai-load'),$('#'+({summary:'summarize',notes:'notes',quiz:'quiz'})[kind]));if(!answer)return;if(kind==='quiz'){try{const clean=answer.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');const data=JSON.parse(clean);if(!Array.isArray(data.questions)||!data.questions.length)throw Error();const el=addMessage('TuonTa',`Practice quiz · ${docName}\nTry answering before revealing each answer.`);for(const [i,q]of data.questions.slice(0,5).entries()){if(typeof q.question!=='string'||typeof q.answer!=='string')continue;const card=document.createElement('div');card.className='quiz-card';const title=document.createElement('p');title.textContent=`${i+1}. ${q.question}`;const details=document.createElement('details'),summary=document.createElement('summary'),p=document.createElement('p');summary.textContent='Reveal suggested answer';p.textContent=q.answer;details.append(summary,p);card.append(title,details);el.append(card);transcript.push({role:'Practice question',text:q.question+'\nAnswer: '+q.answer})}return}catch{addMessage('TuonTa',answer);return}}addMessage('TuonTa',`${kind==='summary'?'Summary':'Study notes'} · ${docName}\n\n${answer}\n\nCoverage: ${context.coverage}`)}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
if(view==='planner')planner();else if(view==='chat'){chat();checkAIStatus()}else home();
window.addEventListener('storage',e=>{if(e.key==='tuonta-v1'&&view==='planner'){try{state=JSON.parse(e.newValue)||{exams:[],sessions:[],minutes:90};$('#minutes').value=state.minutes;renderPlanner()}catch{}}});

async function checkAIStatus(){try{const r=await fetch('/api/ai/status');const data=await r.json();const el=$('#ai-load');el.className='ai-status';el.textContent=data.configured?'Hosted AI is connected. Ask a question to get started.':'Hosted AI is waiting for its API key. The site owner needs to add the GROQ_API_KEY hosting secret.'}catch{const el=$('#ai-load');if(el){el.className='notice';el.textContent='Could not check the AI connection. Refresh to try again.'}}}
